import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { t } from '../common/t';
import { priceLabel } from '../common/money';
import { products, unlockTypes } from './api';
import ProductModal from './ProductModal';
/**
 * "Sell this" inside the tag and group editors: what already sells this
 * item, and a button that opens a product with it filled in. Where most
 * owners start, so most never need to open the Products tab.
 */
export default class SellThis extends Component {
  products = null;
  types = [];
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  load() {
    Promise.all([products(), unlockTypes()]).then(([p, types]) => {
      this.products = p.data.filter(x => x.unlocks.some(u => u.type === this.attrs.type && u.targetId === this.attrs.id));
      this.types = types.data;
      m.redraw();
    });
  }
  view() {
    return m("fieldset", {
      className: "KioskSellThis"
    }, m("legend", null, t('admin.sell_this.legend')), this.products === null ? m(LoadingIndicator, {
      size: "small",
      display: "inline"
    }) : m("div", null, this.products.length ? m("ul", {
      className: "KioskSellThis-list"
    }, this.products.map(p => m("li", null, m("strong", null, p.name), " \u2014 ", p.prices.map(x => priceLabel(x)).join(' / '), ' ', m(Button, {
      className: "Button Button--link",
      onclick: () => this.open(p)
    }, t('admin.products.edit'))))) : m("p", {
      className: "helpText"
    }, t('admin.sell_this.help_' + this.attrs.type)), m(Button, {
      className: "Button",
      icon: "fas fa-store",
      onclick: () => this.open()
    }, this.products.length ? t('admin.sell_this.another') : t('admin.sell_this.button'))));
  }
  open(product) {
    const currency = String(app.data.settings['ernestdefoe-kiosk.currency'] || 'USD');

    // Stacked over the tag or group editor, which stays open underneath.
    app.modal.show(ProductModal, {
      product,
      types: this.types,
      preset: product ? undefined : {
        name: this.attrs.name,
        unlocks: [{
          type: this.attrs.type,
          targetId: this.attrs.id,
          label: this.attrs.name
        }],
        prices: [{
          kind: 'recurring',
          amount: '5',
          interval: 'month',
          currency
        }]
      },
      onsaved: () => this.load()
    }, true);
  }
}